print(r'''
CREATE TEMP TABLE v347_cases(name text,mutation text);
INSERT INTO v347_cases VALUES
 ('positive corrected amount',$q$SELECT set_config('lts.v347_proofs',jsonb_set(current_setting('lts.v347_proofs')::jsonb,'{0,documented_signed_amount}','10')::text,true)$q$),
 ('wrong original amount',$q$SELECT set_config('lts.v347_proofs',jsonb_set(current_setting('lts.v347_proofs')::jsonb,'{0,imported_amount}','11')::text,true)$q$),
 ('wrong row',$q$SELECT set_config('lts.v347_proofs',jsonb_set(current_setting('lts.v347_proofs')::jsonb,'{0,workbook_row}','999')::text,true)$q$),
 ('wrong hash',$q$SELECT set_config('lts.v347_proofs',jsonb_set(current_setting('lts.v347_proofs')::jsonb,'{0,workbook_sha256}','"bad"')::text,true)$q$),
 ('duplicate source',$q$SELECT set_config('lts.v347_proofs',(current_setting('lts.v347_proofs')::jsonb||jsonb_build_array(current_setting('lts.v347_proofs')::jsonb->0))::text,true)$q$),
 ('raw amount changed',$q$UPDATE public.evento_base SET dados=jsonb_set(dados,'{valor}','11')WHERE idx=1$q$),
 ('raw bank changed',$q$UPDATE public.evento_base SET dados=jsonb_set(dados,'{conta}','"Other bank"')WHERE idx=1$q$),
 ('raw date changed',$q$UPDATE public.evento_base SET dados=jsonb_set(dados,'{dia}','"2024-01-02"')WHERE idx=1$q$),
 ('cash proof changed',$q$UPDATE public.lts_reconciliation_evidence SET metadata=metadata||'{"extra":"changed"}'WHERE source_ref='workbook_cash_sign:evento_base:1'$q$),
 ('cash proof pending',$q$UPDATE public.lts_reconciliation_evidence SET status='pending'WHERE source_ref='workbook_cash_sign:evento_base:1'$q$),
 ('cash proof wrong owner',$q$UPDATE public.lts_reconciliation_evidence SET user_id='00000000-0000-4000-8000-000000000002'WHERE source_ref='workbook_cash_sign:evento_base:1'$q$),
 ('cache membership changed',$q$UPDATE public.lts_expense_effective_read_cache SET amount=11 WHERE source_ref='1'AND user_id='00000000-0000-4000-8000-000000000001'$q$);
DO $test$DECLARE r record;m text;BEGIN FOR r IN SELECT * FROM v347_cases LOOP BEGIN
 EXECUTE r.mutation;m:=NULL;BEGIN EXECUTE(SELECT sql FROM v347_sqls WHERE kind='activation');EXCEPTION WHEN raise_exception THEN m:=SQLERRM;END;
 IF m IS NULL OR m NOT LIKE 'V347_%'THEN RAISE EXCEPTION 'Invalid proof accepted or unexpected rejection: % / %',r.name,m;END IF;
 RAISE EXCEPTION USING ERRCODE='V3470',MESSAGE='rollback case';EXCEPTION WHEN SQLSTATE 'V3470'THEN NULL;END;END LOOP;END$test$;
''')
